package com.studenthub.controller;
import com.fasterxml.jackson.databind.ObjectMapper;import com.studenthub.dao.PrivateMessageDAO;import com.studenthub.model.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.util.*;
@WebServlet(name="PollPrivateMessagesServlet",urlPatterns="/messages/poll")
public class PollPrivateMessagesServlet extends HttpServlet{private final PrivateMessageDAO dao=new PrivateMessageDAO();private final ObjectMapper json=new ObjectMapper();@Override protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{try{long conversation=Long.parseLong(q.getParameter("conversationId")),after=Long.parseLong(Optional.ofNullable(q.getParameter("afterMessageId")).orElse("0")),me=(Long)q.getSession().getAttribute("userId");var rows=dao.messages(conversation,me,after);dao.markDelivered(conversation,me);r.setContentType("application/json");r.setCharacterEncoding("UTF-8");json.writeValue(r.getWriter(),Map.of("messages",rows.stream().map(m->message(q,m)).toList(),"receipts",dao.receipts(conversation,me)));}catch(SecurityException e){r.sendError(403);}catch(Exception e){r.sendError(400);}}private Map<String,Object> message(HttpServletRequest q,PrivateMessage m){Map<String,Object> out=new LinkedHashMap<>();out.put("messageId",m.messageId());out.put("senderId",m.senderId());out.put("message",m.message()==null?"":m.message());out.put("createdLabel",m.getCreatedLabel());out.put("status",m.getStatus());Attachment a=m.attachment();if(a!=null){out.put("attachmentId",a.attachmentId());out.put("originalFilename",a.originalFilename());out.put("mimeType",a.mimeType());out.put("fileSize",a.fileSize());out.put("attachmentType",a.isImage()?"IMAGE":a.isVideo()?"VIDEO":a.isAudio()?"AUDIO":"FILE");String url=q.getContextPath()+"/messages/attachments/"+a.attachmentId();out.put("previewUrl",url);out.put("downloadUrl",url+"?download=1");}return out;}}
